def poly(x, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(x))] + [np.prod(x[:, k], axis=1) for j in range(1, d + 1) for k in combinations_with_replacement(range(x.shape[1]), j)])

def prof(X, Y, D):
    from scipy.optimize import least_squares
    for offset in [0, 1, 2, 3]:
        U = X[:, (np.arange(4) + offset) % 4]
        for (name, f) in [('sin', np.sin), ('tanh', np.tanh), ('identity', lambda v: v)]:
            if name == 'identity' and offset > 0:
                continue

            def calc(r):
                Q = np.c_[D, f(r[0] * U + r[1])]
                return Q @ ls(Q, Y) - Y
            rr = least_squares(lambda r: calc(r).ravel(), [1.3, 0.05], bounds=([0.05, -2], [6, 2]), max_nfev=50)
            print(name, offset, np.std(rr.fun), rr.x)
        if offset == 0:
            break
